import React from 'react';
import {
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  Divider,
  Grid,
  List,
  ListItem,
  ListItemText,
  Paper,
  Stack,
  Typography,
} from '@mui/material';
import {
  AccountBalance as FinanceIcon,
  AutoAwesome as WhyIcon,
  CheckCircleOutline as CheckIcon,
  Flag as IndiaIcon,
  Hub as WorkflowIcon,
  Layers as ModulesIcon,
  Nature as FootprintIcon,
  Savings as HotspotIcon,
  Summarize as DisclosureIcon,
  TrendingUp as ValueIcon,
  Verified as CertificationIcon,
} from '@mui/icons-material';
import { WHY_CARBON_INTELLIGENCE_IMAGES } from '../constants/whyCarbonIntelligenceImages';
import { TopicIconBadge } from './shared/TopicIconBadge';
import MarketingHeading from './shared/MarketingHeading';
import { preLoginHorizontalBannerImageSx } from '../constants/bannerIllustrationLayout';
import { Link as RouterLink } from 'react-router-dom';
import { alpha, useTheme } from '@mui/material/styles';
import { useRegistration } from '../context/RegistrationContext';
import { BRAND_PATENT_PENDING_LABEL } from '../constants/brand';
import {
  WHY_CARBON_INTELLIGENCE_CERTIFICATION,
  WHY_CARBON_INTELLIGENCE_CTA,
  WHY_CARBON_INTELLIGENCE_INDIA_CONTEXT,
  WHY_CARBON_INTELLIGENCE_PAGE,
  WHY_CARBON_INTELLIGENCE_PLATFORM_MODULES,
  WHY_CARBON_INTELLIGENCE_VALUE_PILLARS,
  WHY_CARBON_INTELLIGENCE_WORKFLOW,
} from '../constants/whyCarbonIntelligenceContent';

const WhyCarbonIntelligencePage: React.FC = () => {
  const theme = useTheme();
  const { isRegistered } = useRegistration();
  const pricingVisible = true;
  const isDark = theme.palette.mode === 'dark';

  const pillarVisuals = [
    { icon: FootprintIcon, image: WHY_CARBON_INTELLIGENCE_IMAGES.footprint },
    { icon: HotspotIcon, image: WHY_CARBON_INTELLIGENCE_IMAGES.hotspots },
    { icon: DisclosureIcon, image: WHY_CARBON_INTELLIGENCE_IMAGES.disclosure },
    { icon: FinanceIcon, image: WHY_CARBON_INTELLIGENCE_IMAGES.finance },
  ] as const;

  return (
    <Box sx={{ maxWidth: 960, mx: 'auto', py: { xs: 2, md: 3 } }}>
      <Stack direction="row" spacing={1.5} alignItems="center" sx={{ mb: 2 }}>
        <TopicIconBadge size="large">
          <WhyIcon />
        </TopicIconBadge>
        <Box>
          <MarketingHeading level="h1">
            {WHY_CARBON_INTELLIGENCE_PAGE.title}
          </MarketingHeading>
          <Typography variant="subtitle1" color="primary.main" sx={{ fontWeight: 700 }}>
            {WHY_CARBON_INTELLIGENCE_PAGE.subtitle} · {WHY_CARBON_INTELLIGENCE_PAGE.tagline}
          </Typography>
        </Box>
      </Stack>

      <Typography variant="body1" color="text.secondary" sx={{ mb: 3, maxWidth: 720 }}>
        {WHY_CARBON_INTELLIGENCE_PAGE.intro}
      </Typography>

      <Box
        component="img"
        src={WHY_CARBON_INTELLIGENCE_IMAGES.hero}
        alt="Why Carbon Intelligence — Sustainow Carbon Intelligence for Indian MSMEs"
        sx={{
          ...preLoginHorizontalBannerImageSx,
          maxWidth: '100%',
          mb: 3,
          borderRadius: 3,
          border: `1px solid ${alpha(theme.palette.divider, 0.6)}`,
          boxShadow: theme.shadows[4],
        }}
      />

      <Paper
        variant="outlined"
        sx={{
          p: { xs: 2, md: 2.5 },
          mb: 3,
          borderStyle: 'dashed',
          borderColor: alpha(theme.palette.primary.main, 0.35),
          bgcolor: alpha(theme.palette.primary.main, isDark ? 0.06 : 0.04),
        }}
      >
        <Typography variant="body1" sx={{ fontWeight: 600 }}>
          {WHY_CARBON_INTELLIGENCE_PAGE.valueLead}
        </Typography>
      </Paper>

      <Paper
        component="section"
        aria-labelledby="why-sci-certification-heading"
        elevation={0}
        sx={{
          p: { xs: 2, md: 2.5 },
          mb: 4,
          borderRadius: 3,
          border: `2px solid ${alpha(theme.palette.warning.main, isDark ? 0.55 : 0.45)}`,
          bgcolor: alpha(theme.palette.warning.main, isDark ? 0.1 : 0.06),
        }}
      >
        <Stack
          direction={{ xs: 'column', sm: 'row' }}
          spacing={1.5}
          alignItems={{ xs: 'flex-start', sm: 'center' }}
          justifyContent="space-between"
          sx={{ mb: 1.5 }}
        >
          <Stack direction="row" spacing={1.5} alignItems="center">
            <CertificationIcon color="warning" />
            <MarketingHeading level="h3" id="why-sci-certification-heading">
              {WHY_CARBON_INTELLIGENCE_CERTIFICATION.title}
            </MarketingHeading>
          </Stack>
          <Chip
            label={WHY_CARBON_INTELLIGENCE_CERTIFICATION.statusLabel}
            color="warning"
            size="small"
            sx={{ fontWeight: 700 }}
          />
        </Stack>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
          {WHY_CARBON_INTELLIGENCE_CERTIFICATION.lead}
        </Typography>
        <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 0.25 }}>
          {WHY_CARBON_INTELLIGENCE_CERTIFICATION.certifyingBodyLabel}
        </Typography>
        <Typography variant="body2" sx={{ fontWeight: 600, mb: 2 }}>
          {WHY_CARBON_INTELLIGENCE_CERTIFICATION.certifyingBody}
        </Typography>
        <Grid container spacing={2} sx={{ mb: 2 }}>
          {WHY_CARBON_INTELLIGENCE_CERTIFICATION.standards.map((standard) => (
            <Grid item xs={12} sm={6} key={standard.label}>
              <Card variant="outlined" sx={{ height: '100%', bgcolor: 'background.paper' }}>
                <CardContent sx={{ py: 1.5, '&:last-child': { pb: 1.5 } }}>
                  <Chip label={standard.label} size="small" color="primary" sx={{ mb: 1, fontWeight: 700 }} />
                  <Typography variant="body2" color="text.secondary">
                    {standard.detail}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
        <Typography variant="caption" color="text.secondary">
          {WHY_CARBON_INTELLIGENCE_CERTIFICATION.disclaimer}
        </Typography>
      </Paper>

      <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 2 }}>
        <ValueIcon color="primary" />
        <MarketingHeading level="h2">
          What Carbon Intelligence helps you achieve
        </MarketingHeading>
      </Stack>
      <Grid container spacing={2} sx={{ mb: 4 }}>
        {WHY_CARBON_INTELLIGENCE_VALUE_PILLARS.map((pillar, index) => {
          const visual = pillarVisuals[index] ?? pillarVisuals[0];
          const PillarIcon = visual.icon;
          return (
          <Grid item xs={12} sm={6} key={pillar.title}>
            <Card
              variant="outlined"
              sx={{
                height: '100%',
                overflow: 'hidden',
                transition: 'box-shadow 0.2s, transform 0.2s',
                '&:hover': {
                  boxShadow: theme.shadows[4],
                  transform: 'translateY(-2px)',
                },
              }}
            >
              <Box
                component="img"
                src={visual.image}
                alt=""
                aria-hidden
                sx={{
                  width: '100%',
                  height: 100,
                  objectFit: 'cover',
                  objectPosition: 'top',
                  opacity: isDark ? 0.85 : 1,
                }}
              />
              <CardContent>
                <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 1 }}>
                  <TopicIconBadge size="small">
                    <PillarIcon fontSize="small" />
                  </TopicIconBadge>
                  <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>
                    {pillar.title}
                  </Typography>
                </Stack>
                <Typography variant="body2" color="text.secondary">
                  {pillar.description}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
          );
        })}
      </Grid>

      <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 2 }}>
        <ModulesIcon color="primary" />
        <MarketingHeading level="h2">
          Platform at a glance
        </MarketingHeading>
      </Stack>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        An abstract map of the signed-in workspace—each module builds on the same underlying data
        and emission-factor logic.
      </Typography>
      <Grid container spacing={2} sx={{ mb: 4 }}>
        {WHY_CARBON_INTELLIGENCE_PLATFORM_MODULES.map((module) => (
          <Grid item xs={12} md={6} key={module.title}>
            <Paper variant="outlined" sx={{ p: 2, height: '100%' }}>
              <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 0.5 }}>
                {module.title}
              </Typography>
              <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
                {module.summary}
              </Typography>
              <List dense disablePadding>
                {module.outcomes.map((outcome) => (
                  <ListItem key={outcome} disableGutters sx={{ py: 0.25 }}>
                    <CheckIcon color="primary" fontSize="small" sx={{ mr: 1, flexShrink: 0 }} />
                    <ListItemText
                      primary={outcome}
                      primaryTypographyProps={{ variant: 'body2', color: 'text.secondary' }}
                    />
                  </ListItem>
                ))}
              </List>
            </Paper>
          </Grid>
        ))}
      </Grid>

      <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 2 }}>
        <WorkflowIcon color="primary" />
        <MarketingHeading level="h2">
          {WHY_CARBON_INTELLIGENCE_WORKFLOW.title}
        </MarketingHeading>
      </Stack>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        {WHY_CARBON_INTELLIGENCE_WORKFLOW.lead}
      </Typography>
      <Grid container spacing={2} sx={{ mb: 4 }}>
        {WHY_CARBON_INTELLIGENCE_WORKFLOW.steps.map((step) => (
          <Grid item xs={12} sm={6} md={3} key={step.step}>
            <Paper
              variant="outlined"
              sx={{
                p: 2,
                height: '100%',
                borderColor: alpha(theme.palette.primary.main, isDark ? 0.4 : 0.25),
              }}
            >
              <Chip
                label={step.step}
                size="small"
                color="primary"
                variant="outlined"
                sx={{ mb: 1, fontWeight: 700 }}
              />
              <Typography variant="subtitle2" sx={{ fontWeight: 700, mb: 0.5 }}>
                {step.title}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                {step.description}
              </Typography>
            </Paper>
          </Grid>
        ))}
      </Grid>

      <Card variant="outlined" sx={{ mb: 4 }}>
        <CardContent>
          <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 1.5 }}>
            <IndiaIcon color="primary" />
            <MarketingHeading level="h3">
              {WHY_CARBON_INTELLIGENCE_INDIA_CONTEXT.title}
            </MarketingHeading>
          </Stack>
          {WHY_CARBON_INTELLIGENCE_INDIA_CONTEXT.paragraphs.map((paragraph) => (
            <Typography key={paragraph.slice(0, 40)} variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
              {paragraph}
            </Typography>
          ))}
        </CardContent>
      </Card>

      <Divider sx={{ mb: 3 }} />

      <Paper
        variant="outlined"
        sx={{
          p: { xs: 2, md: 3 },
          display: 'flex',
          flexDirection: { xs: 'column', sm: 'row' },
          alignItems: { xs: 'flex-start', sm: 'center' },
          justifyContent: 'space-between',
          gap: 2,
        }}
      >
        <Box>
          <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 0.5 }}>
            {WHY_CARBON_INTELLIGENCE_CTA.title}
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
            {WHY_CARBON_INTELLIGENCE_CTA.description}
          </Typography>
          <Chip size="small" label={BRAND_PATENT_PENDING_LABEL} color="primary" variant="outlined" />
        </Box>
        <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1}>
          {pricingVisible ? (
            <Button component={RouterLink} to="/pricing" variant="outlined">
              {WHY_CARBON_INTELLIGENCE_CTA.pricingLabel}
            </Button>
          ) : null}
          <Button
            component={RouterLink}
            to={isRegistered ? '/dashboard' : '/register?type=msme'}
            variant="contained"
          >
            {isRegistered ? WHY_CARBON_INTELLIGENCE_CTA.workspaceLabel : WHY_CARBON_INTELLIGENCE_CTA.registerLabel}
          </Button>
        </Stack>
      </Paper>
    </Box>
  );
};

export default WhyCarbonIntelligencePage;
